def comp(cid, speaker, with_text, back, left, home, joined):
    d=json.loads(json.dumps(json.load(open('src/content/dialogues/crystal.json'))['comp_shepot']).replace('shepot',cid))
    d['speaker']=speaker
    d['portrait']=f"portrait_{cid}"
    n=d['nodes']
    n['with']['text']=with_text; n['back']['text']=back; n['left']['text']=left; n['home']['text']=home; n['joined']['text']=joined
    return d
D['comp_lelya']=comp('lelya',"Лёля Реле","Лёля что-то подкручивает в Искровике. — Слушаю. Только быстро.","— Позади так позади. Оттуда лучше видно, что чинить.","— Вернусь в мастерские. Насосы без меня скучают.","Лёля сидит под мотором в мастерских. — Опять дорога? Дай гаечный ключ найду.","— Идём. Регламент подождёт.")
D['comp_vedro']=comp('vedro',"Ведро","— СЛУШАЮ. — Линза Ведра мигает.","— ДИСТАНЦИЯ: ПОЗАДИ. ПРИНЯТО.","— ВОЗВРАЩАЮСЬ НА ОБХОД. ТУННЕЛИ. ОЖИДАЮ.","Ведро стоит у трубы в туннелях. — ОЖИДАЮ.","— СЛЕДУЮ.")
open('src/content/dialogues/upper.json','w').write(json.dumps(D,ensure_ascii=False,indent=1)+'\n')

